std::optional<Integer> id_number(const StableId& id,const StableId& prefix,Integer next){const auto head=prefix+":";if(id.rfind(head,0)!=0)return {};const auto text=id.substr(head.size());Integer number=0;auto p=std::from_chars(text.data(),text.data()+text.size(),number);if(p.ec!=std::errc{}||p.ptr!=text.data()+text.size()||number<=0||number>=next||std::to_string(number)!=text)return {};return number;}
Outcome<Integer> observed(const CommonStore& c,const DynamicStepInput* phase){if(!phase)return {true,c.tick(),{}};if(c.tick()==std::numeric_limits<Integer>::max()||phase->from_tick!=c.tick()||phase->to_tick!=c.tick()+1)return {false,{},common_failure("InvalidTaskShopOrderPhase").error};return {true,phase->to_tick,{}};}
bool before(const CommonStore& c,const StableId& a,const StableId& b){const auto& list=c.state().facts.order();auto x=std::find(list.begin(),list.end(),a),y=std::find(list.begin(),list.end(),b);return x!=list.end()&&y!=list.end()&&x<y;}
const TaskShopOrderBinding* binding(const TaskShopOrderState& s,const StableId& task){auto i=s.by_task.find(task);return i==s.by_task.end()?nullptr:s.bindings.find(i->second);}
PrivateShopOrderExecution execution(const CommonStore& c,const TaskShopOrderBinding& b,const TaskShopOrderSettlement& receipt){PrivateShopOrderExecution result;result.source_identity=c.state().identity;result.order_id=b.order_id;result.task_id=b.task_id;result.settlement_id=receipt.settlement_id;result.receipt_fact_id=receipt.fact_id;result.terms=b.terms;result.outcome=receipt.outcome;result.completed_tick=receipt.tick;result.delivered_quantity=receipt.delivered_quantity;result.paid_price=receipt.paid_price;result.refunded_price=receipt.refunded_price;for(const auto& lot:receipt.lots)result.lots.push_back({lot.source_lot_id,lot.destination_lot_id,lot.quantity});return result;}
