Status validate_task_shop_order_ledger(const CommonStore& common,const TaskState& tasks,const TaskShopOrderState& state,const DynamicStepInput* phase){
    auto valid=validate_task_shop_order_acceptances(common,tasks,state);if(!valid.ok)return valid;valid=validate_task_shop_order_estate_links(common,state);if(!valid.ok)return valid;auto now=observed(common,phase);if(!now.ok)return {false,{},now.error};if(state.settlements.size()>65536||state.actions.size()>65536||state.interruptions.size()>65536)return common_failure("TaskShopOrderHistoryLimit");std::set<StableId> terminated,settlement_ids,source_actions,active_tasks;std::size_t headers=0,interruption_headers=0;
    for(const auto& row:state.settlements.rows()){
        const auto& r=row.second;const auto* b=binding(state,r.task_id);const auto* task=tasks.tasks.find(r.task_id);const auto* header=common.state().facts.find(row.first);const auto n=id_number(row.first,task_shop_order_settled_kind,common.state().next_instance_id),settled=id_number(r.settlement_id,"settlement",common.state().next_instance_id);const auto accepted=b?id_number(b->fact_id,task_shop_order_acceptance_prefix,common.state().next_instance_id):std::optional<Integer>{};
        if(!b||!task||row.first!=r.fact_id||!n||!settled||!accepted||*accepted>=*settled||*settled>=*n||!header||header->id!=row.first||header->kind!=task_shop_order_settled_kind||header->domain!=task_shop_order_domain||!before(common,b->fact_id,row.first)||r.order_id!=b->order_id||!terminated.insert(r.task_id).second||!settlement_ids.insert(r.settlement_id).second||r.tick<b->terms.accepted_tick||r.tick>now.value||task->settlement_id!=r.settlement_id||!task->reported_tick||*task->reported_tick!=r.tick||r.from_inventory_id!=b->terms.stock_inventory_id||r.to_inventory_id!=b->terms.client_inventory_id||r.from_wallet_id!=b->terms.client_wallet_id||r.to_wallet_id!=b->terms.shop_wallet_id||!owner_equal(r.from_container_owner,{Owner::Kind::actor,b->terms.proprietor_actor_id,{}})||!owner_equal(r.to_container_owner,b->terms.original_client)||bool(r.from_container_owner.extra)||bool(r.to_container_owner.extra)||r.refunded_price!=0)return common_failure("InvalidTaskShopOrderSettlement",row.first);
        if(r.outcome=="cancelled"){if((r.termination!="cancelled_by_proprietor"&&r.termination!="deadline_elapsed"&&r.termination!=task_shop_order_estate_termination)||(r.termination=="deadline_elapsed"&&r.tick<=b->terms.deadline_tick)||task->status!="cancelled"||r.action_started_tick!=-1||r.delivered_quantity||r.paid_price||!r.source_action_id.empty()||!r.lots.empty()||task->objective_completed_tick)return common_failure("InvalidTaskShopOrderCancellation",row.first);}
        else if(r.outcome=="delivered"){
            const auto action=id_number(r.source_action_id,"action",common.state().next_instance_id);if(r.termination!="delivery"||task->status!="success"||!task->objective_completed_tick||*task->objective_completed_tick!=r.tick||!action||*action<=*accepted||*action>=*settled||!source_actions.insert(r.source_action_id).second||r.tick>b->terms.deadline_tick||r.action_started_tick<b->terms.accepted_tick||r.action_started_tick>=r.tick||r.tick-r.action_started_tick!=task_handover_ticks||r.delivered_quantity!=b->terms.quantity||r.paid_price!=b->terms.contract_price||r.lots.empty())return common_failure("InvalidTaskShopOrderDelivery",row.first);
            Integer total=0;std::set<StableId> origins,destinations;for(const auto& lot:r.lots){const auto origin=id_number(lot.source_lot_id,"lot",common.state().next_instance_id),destination=id_number(lot.destination_lot_id,"lot",common.state().next_instance_id);if(!origin||!destination||*origin>=*destination||*destination>=*settled||*destination<=*action||lot.item_id!=b->terms.item_id||lot.quantity<1||lot.quantity>b->terms.quantity-total||lot.source_before<lot.quantity||lot.source_after!=lot.source_before-lot.quantity||!owner_equal(lot.source_owner,r.from_container_owner)||!owner_equal(lot.destination_owner,r.to_container_owner)||bool(lot.source_owner.extra)||bool(lot.destination_owner.extra)||!origins.insert(lot.source_lot_id).second||!destinations.insert(lot.destination_lot_id).second)return common_failure("InvalidTaskShopOrderLotSource",row.first);total+=lot.quantity;}if(total!=b->terms.quantity)return common_failure("TaskShopOrderQuantityMismatch",row.first);
        }else return common_failure("UnsupportedTaskShopOrderOutcome",row.first);
    }
    for(const auto& row:state.interruptions.rows()){
        const auto& r=row.second;const auto& a=r.source;const auto* b=binding(state,a.task_id);const auto* head=common.state().facts.find(row.first);const auto n=id_number(row.first,task_shop_order_interrupted_kind,common.state().next_instance_id),action=id_number(a.action_id,"action",common.state().next_instance_id),session=id_number(a.session_id,"interaction",common.state().next_instance_id),accepted=b?id_number(b->fact_id,task_shop_order_acceptance_prefix,common.state().next_instance_id):std::optional<Integer>{};
        if(row.first!=r.fact_id||!b||!head||head->id!=row.first||head->kind!=task_shop_order_interrupted_kind||head->domain!=task_shop_order_domain||!n||!action||!session||!accepted||*accepted>=*action||*session>=*action||*action>=*n||!before(common,b->fact_id,row.first)||!source_actions.insert(a.action_id).second||state.actions.find(a.action_id)||r.tick>now.value||a.started_tick<b->terms.accepted_tick||r.tick<=a.started_tick||r.tick-a.started_tick!=task_handover_ticks||r.code.empty()||a.context.kind||a.context.encounter_id||a.context.input_error||a.context.provider_actor_id!=b->terms.original_client.id||a.context.place_id.empty()||a.context.role_id.empty()||a.dialogue_id.empty()||a.node_id.empty())return common_failure("InvalidTaskShopOrderInterruption",row.first);
        if(const auto* core=common.action(a.action_id)){if(!phase||core->kind!="task_shop_order_deliver"||core->actor_id!=b->terms.proprietor_actor_id||core->participants!=std::vector<StableId>{b->terms.proprietor_actor_id,b->terms.original_client.id}||core->start_tick!=a.started_tick||core->remaining_ticks!=0)return common_failure("TaskShopOrderInterruptedActionMismatch",row.first);}
        for(const auto& final:state.settlements.rows())if(final.second.task_id==a.task_id){const auto end=id_number(final.second.settlement_id,"settlement",common.state().next_instance_id);if(!end||*n>=*end||r.tick>final.second.tick||!before(common,row.first,final.first))return common_failure("TaskShopOrderInterruptionAfterSettlement",row.first);}
    }
    for(const auto& row:common.state().facts.rows())if(row.second.kind==task_shop_order_settled_kind){if(row.second.domain!=task_shop_order_domain||!state.settlements.find(row.first))return common_failure("MissingTaskShopOrderSettlement",row.first);++headers;}else if(row.second.kind==task_shop_order_interrupted_kind){if(row.second.domain!=task_shop_order_domain||!state.interruptions.find(row.first))return common_failure("MissingTaskShopOrderInterruption",row.first);++interruption_headers;}else if(row.second.domain==task_shop_order_domain&&row.second.kind!=task_shop_order_acceptance_kind)return common_failure("UnknownTaskShopOrderFact",row.first);if(interruption_headers!=state.interruptions.size())return common_failure("MissingTaskShopOrderInterruption");if(headers!=state.settlements.size())return common_failure("MissingTaskShopOrderSettlement");
    for(const auto& row:state.actions.rows()){
        const auto& a=row.second;const auto* b=binding(state,a.task_id);const auto* core=common.action(a.action_id);const auto* task=tasks.tasks.find(a.task_id);const auto action_number=id_number(a.action_id,"action",common.state().next_instance_id),session_number=id_number(a.session_id,"interaction",common.state().next_instance_id),accepted_number=b?id_number(b->fact_id,task_shop_order_acceptance_prefix,common.state().next_instance_id):std::optional<Integer>{};if(!action_number||!session_number||!accepted_number||*session_number>=*action_number||*accepted_number>=*action_number||row.first!=a.action_id||!b||!core||!task||task->status!="active"||terminated.count(a.task_id)||!active_tasks.insert(a.task_id).second||!source_actions.insert(a.action_id).second||core->id!=a.action_id||core->kind!="task_shop_order_deliver"||core->actor_id!=b->terms.proprietor_actor_id||a.started_tick<task->accepted_tick||a.started_tick>common.tick()||core->start_tick!=a.started_tick||core->remaining_ticks<0||core->remaining_ticks>task_handover_ticks||(!phase&&core->remaining_ticks==0)||core->participants!=std::vector<StableId>{b->terms.proprietor_actor_id,b->terms.original_client.id}||a.context.provider_actor_id!=b->terms.original_client.id||a.context.kind||a.context.encounter_id||a.context.input_error||a.context.role_id.empty()||a.context.place_id.empty()||a.dialogue_id.empty()||a.node_id.empty()||!id_number(a.session_id,"interaction",common.state().next_instance_id))return common_failure("InvalidTaskShopOrderAction",row.first);for(const auto& person:core->participants)if(!common.actor(person)||common.actor(person)->action_id!=a.action_id)return common_failure("TaskShopOrderOccupationMismatch",row.first);
    }
    for(const auto& row:state.bindings.rows()){
        const auto& b=row.second;const auto* task=tasks.tasks.find(b.task_id);const ReservationRef key{ReservationRef::Kind::contract,b.reservation_id};const auto* wallet=common.wallet(b.terms.client_wallet_id);if(!wallet)return common_failure("TaskShopOrderClientWalletMissing",row.first);Integer amount=-1;for(const auto& r:wallet->reserved)if(r.action_id==key){if(amount!=-1)return common_failure("DuplicateTaskShopOrderReservation",row.first);amount=r.amount;}
        for(const auto& other:common.state().wallets.rows()){if(other.second.owner.kind==Owner::Kind::task&&other.second.owner.id==b.task_id)return common_failure("TaskShopOrderUnexpectedEscrow",row.first);for(const auto& r:other.second.reserved)if(r.action_id==key&&other.first!=b.terms.client_wallet_id)return common_failure("TaskShopOrderForeignReservation",row.first);}for(const auto& inventory:common.state().inventories.rows())for(const auto& lot:inventory.second.lots)if(lot.reserved_by==key||(lot.owner.kind==Owner::Kind::task&&lot.owner.id==b.task_id))return common_failure("TaskShopOrderUnexpectedCargoReservation",row.first);
        if(terminated.count(b.task_id)){if(amount!=-1||active_tasks.count(b.task_id))return common_failure("TaskShopOrderFinalReservationMismatch",row.first);}else if(task->status!="active"||!task->settlement_id.empty()||task->reported_tick||task->objective_completed_tick||amount!=b.terms.contract_price||!owner_equal(wallet->owner,b.terms.original_client))return common_failure("TaskShopOrderActiveReservationMismatch",row.first);
    }
    return common_success();
}
Status validate_task_shop_order_execution(const CommonStore& common,const TaskState& tasks,const TaskShopOrderState& state,const PrivateShopOrderRead& shop,const DynamicStepInput* phase){auto valid=validate_task_shop_order_ledger(common,tasks,state,phase);if(!valid.ok)return valid;if(!phase)for(const auto& row:common.state().actions.rows())if(row.second.kind=="task_shop_order_deliver"&&!state.actions.find(row.first))return common_failure("MissingTaskShopOrderAction",row.first);for(const auto& row:state.bindings.rows()){const auto& b=row.second;auto source=shop.private_shop_order_source(b.order_id);if(!source.ok)return {false,{},source.error};const auto& identity=common.state().identity;if(!source.value||source.value->source_identity.world_id!=identity.world_id||source.value->source_identity.execution_epoch!=identity.execution_epoch||source.value->source_identity.revision!=identity.revision||source.value->source_identity.tick!=identity.tick||source.value->status!="accepted"||source.value->task_id!=b.task_id||source.value->acceptance_fact_id!=b.fact_id||source.value->issue_fact_id!=b.order_issue_fact_id||!task_shop_order_terms_equal(source.value->terms,b.terms))return common_failure("TaskShopOrderSourceMismatch",row.first);for(const auto& action:state.actions.rows())if(action.second.task_id==b.task_id){const auto& a=action.second;const auto& original=source.value->client_declaration;if(a.context.place_id!=original.place_id||a.context.role_id!=original.role_id||a.context.provider_actor_id!=original.provider_actor_id||a.dialogue_id!=original.dialogue_id||a.node_id!=original.node_id)return common_failure("TaskShopOrderActionSourceMismatch",action.first);}for(const auto& failure:state.interruptions.rows())if(failure.second.source.task_id==b.task_id){const auto& a=failure.second.source;const auto& original=source.value->client_declaration;if(a.context.place_id!=original.place_id||a.context.role_id!=original.role_id||a.context.provider_actor_id!=original.provider_actor_id||a.dialogue_id!=original.dialogue_id||a.node_id!=original.node_id)return common_failure("TaskShopOrderInterruptionSourceMismatch",failure.first);}}return common_success();}
Outcome<std::optional<PrivateShopOrderExecution>> TaskShopOrderExecutionAccess::private_shop_order_execution(const StableId& id)const{auto valid=validate_task_shop_order_ledger(common_,tasks_,state_,phase_);if(!valid.ok)return {false,{},valid.error};const auto* b=binding(state_,id);if(!b)return {true,std::nullopt,{}};for(const auto& row:state_.settlements.rows())if(row.second.task_id==id)return {true,execution(common_,*b,row.second),{}};return {true,std::nullopt,{}};}
